code:
static unsigned int wpas_ml_parse_assoc(struct wpa_supplicant *wpa_s,
					struct ieee802_11_elems *elems,
					struct ml_sta_link_info *ml_info)
{
	struct wpabuf *mlbuf;
	struct ieee80211_eht_ml *ml;
	size_t ml_len;
	struct eht_ml_basic_common_info *common_info;
	const u8 *pos;
	u16 eml_capa = 0, mld_capa = 0;
	const u16 control = MULTI_LINK_CONTROL_TYPE_BASIC |
		BASIC_MULTI_LINK_CTRL_PRES_LINK_ID |
		BASIC_MULTI_LINK_CTRL_PRES_BSS_PARAM_CH_COUNT;
	u8 expected_common_info_len = 9;
	unsigned int i = 0;
	u16 ml_control;

	if (!wpa_s->valid_links || !elems->basic_mle || !elems->basic_mle_len)
		return 0;

	mlbuf = ieee802_11_defrag(elems->basic_mle, elems->basic_mle_len, true);
	if (!mlbuf)
		return 0;

	ml = (struct ieee80211_eht_ml *) wpabuf_head(mlbuf);
	ml_len = wpabuf_len(mlbuf);
	if (ml_len < sizeof(*ml))
		goto out;

	os_memset(ml_info, 0, sizeof(*ml_info) * MAX_NUM_MLD_LINKS);

	ml_control = le_to_host16(ml->ml_control);

	if ((ml_control & control) != control) {
		wpa_printf(MSG_DEBUG, "MLD: Invalid presence BM=0x%x",
			   ml_control);
		goto out;
	}

	if (ml_control & BASIC_MULTI_LINK_CTRL_PRES_EML_CAPA) {
		wpa_printf(MSG_DEBUG, "MLD: EML capabilities included");
		expected_common_info_len += 2;
	}

	if (ml_control & BASIC_MULTI_LINK_CTRL_PRES_MLD_CAPA) {
		wpa_printf(MSG_DEBUG, "MLD: MLD capabilities included");
		expected_common_info_len += 2;
	}

	if (ml_control & BASIC_MULTI_LINK_CTRL_PRES_MSD_INFO) {
		wpa_printf(MSG_DEBUG,
			   "MLD: Unexpected: medium sync delay info present");
		expected_common_info_len += 2;
	}

	if (ml_control & BASIC_MULTI_LINK_CTRL_PRES_AP_MLD_ID) {
		wpa_printf(MSG_DEBUG,
			   "MLD: Unexpected: MLD ID present");
		expected_common_info_len++;
	}

	if (sizeof(*ml) + expected_common_info_len > ml_len) {
		wpa_printf(MSG_DEBUG,
			   "MLD: Not enough bytes for common info. ml_len=%zu",
			   ml_len);
		goto out;
	}

	common_info = (struct eht_ml_basic_common_info *) ml->variable;
	if (common_info->len < expected_common_info_len) {
		wpa_printf(MSG_DEBUG,
			   "MLD: Invalid common info len=%u. expected=%u",
			   common_info->len, expected_common_info_len);
		goto out;
	}

	wpa_printf(MSG_DEBUG, "MLD: address: " MACSTR,
		   MAC2STR(common_info->mld_addr));

	if (!ether_addr_equal(wpa_s->ap_mld_addr, common_info->mld_addr)) {
		wpa_printf(MSG_DEBUG, "MLD: Mismatching MLD address (expected "
			   MACSTR ")", MAC2STR(wpa_s->ap_mld_addr));
		goto out;
	}

	pos = common_info->variable;

	/* Store the information for the association link */
	ml_info[i].link_id = *pos;
	pos++;

	/* Skip the BSS Parameters Change Count */
	pos++;

	/* Skip the Medium Synchronization Delay Information if present  */
	if (ml_control & BASIC_MULTI_LINK_CTRL_PRES_MSD_INFO)
		pos += 2;

	if (ml_control & BASIC_MULTI_LINK_CTRL_PRES_EML_CAPA) {
		eml_capa = WPA_GET_LE16(pos);
		pos += 2;
	}

	if (ml_control & BASIC_MULTI_LINK_CTRL_PRES_MLD_CAPA) {
		mld_capa = WPA_GET_LE16(pos);
		pos += 2;
	}

	wpa_printf(MSG_DEBUG,
		   "MLD: link_id=%u, eml=0x%x, mld=0x%x",
		   ml_info[i].link_id, eml_capa, mld_capa);

	i++;

	pos = ((u8 *) common_info) + common_info->len;
	ml_len -= sizeof(*ml) + common_info->len;
	while (ml_len > 2 && i < MAX_NUM_MLD_LINKS) {
		size_t sub_elem_len, sta_info_len, sta_info_len_min;
		u8 nstr_bitmap_len = 0;
		u16 ctrl;
		const u8 *end;
		int num_frag_subelems;

		num_frag_subelems =
			ieee802_11_defrag_mle_subelem(mlbuf, pos,
						      &sub_elem_len);
		if (num_frag_subelems < 0) {
			wpa_printf(MSG_DEBUG,
				   "MLD: Failed to parse MLE subelem");
			goto out;
		}

		ml_len -= num_frag_subelems * 2;

		wpa_printf(MSG_DEBUG, "MLD: Subelement len=%zu", sub_elem_len);

		if (sub_elem_len > ml_len - 2) {
			wpa_printf(MSG_DEBUG,
				   "MLD: Invalid link info len: %zu > %zu",
				   2 + sub_elem_len, ml_len);
			goto out;
		}

		switch (*pos) {
		case MULTI_LINK_SUB_ELEM_ID_PER_STA_PROFILE:
			break;
		case MULTI_LINK_SUB_ELEM_ID_FRAGMENT:
		case MULTI_LINK_SUB_ELEM_ID_VENDOR:
			wpa_printf(MSG_DEBUG,
				   "MLD: Skip subelement id=%u, len=%zu",
				   *pos, sub_elem_len);
			pos += 2 + sub_elem_len;
			ml_len -= 2 + sub_elem_len;
			continue;
		default:
			wpa_printf(MSG_DEBUG, "MLD: Unknown subelement ID=%u",
				   *pos);
			goto out;
		}

		end = pos + 2 + sub_elem_len;

		/* Skip the subelement ID and the length */
		pos += 2;
		ml_len -= 2;

		if (end - pos < 2)
			goto out;

		/* Get the station control field */
		ctrl = WPA_GET_LE16(pos);

		pos += 2;
		ml_len -= 2;

		if (!(ctrl & BASIC_MLE_STA_CTRL_COMPLETE_PROFILE)) {
			wpa_printf(MSG_DEBUG,
				   "MLD: Per STA complete profile expected");
			goto out;
		}

		if (!(ctrl & BASIC_MLE_STA_CTRL_PRES_STA_MAC)) {
			wpa_printf(MSG_DEBUG,
				   "MLD: Per STA MAC address not present");
			goto out;
		}

		if (!(ctrl & BASIC_MLE_STA_CTRL_PRES_TSF_OFFSET)) {
			wpa_printf(MSG_DEBUG,
				   "MLD: Per STA TSF offset not present");
			goto out;
		}

		if (!(ctrl & BASIC_MLE_STA_CTRL_PRES_BEACON_INT)) {
			wpa_printf(MSG_DEBUG,
				   "MLD: Beacon interval not present");
			goto out;
		}

		if (!(ctrl & BASIC_MLE_STA_CTRL_PRES_DTIM_INFO)) {
			wpa_printf(MSG_DEBUG,
				   "MLD:  DTIM information not present");
			goto out;
		}

		if (ctrl & BASIC_MLE_STA_CTRL_PRES_NSTR_LINK_PAIR) {
			if (ctrl & BASIC_MLE_STA_CTRL_NSTR_BITMAP)
				nstr_bitmap_len = 2;
			else
				nstr_bitmap_len = 1;
		}

		if (!(ctrl & BASIC_MLE_STA_CTRL_PRES_BSS_PARAM_COUNT)) {
			wpa_printf(MSG_DEBUG,
				   "MLD:  BSS params change count not present");
			goto out;
		}

		sta_info_len_min = 1 + ETH_ALEN + 8 + 2 + 2 + 1 +
			nstr_bitmap_len;
		if (sta_info_len_min > ml_len ||
		    sta_info_len_min > (size_t) (end - pos) ||
		    sta_info_len_min + 2 > sub_elem_len) {
			wpa_printf(MSG_DEBUG,
				   "MLD: Invalid STA info min len=%zu, len=%u",
				   sta_info_len_min, *pos);
			goto out;
		}
		sta_info_len = *pos;
		if (sta_info_len > ml_len ||
		    sta_info_len > sub_elem_len - 2 ||
		    sta_info_len < sta_info_len_min) {
			wpa_printf(MSG_DEBUG,
				   "MLD: Invalid STA info min len=%zu, len=%zu",
				   sta_info_len_min, sta_info_len);
			goto out;
		}

		/* Get the link address */
		wpa_printf(MSG_DEBUG,
			   "MLD: link addr: " MACSTR " nstr BM len=%u",
			   MAC2STR(pos + 1), nstr_bitmap_len);

		ml_info[i].link_id = ctrl & BASIC_MLE_STA_CTRL_LINK_ID_MASK;
		os_memcpy(ml_info[i].bssid, pos + 1, ETH_ALEN);

		pos += sta_info_len;
		ml_len -= sta_info_len;

		wpa_printf(MSG_DEBUG, "MLD: sub_elem_len=%zu, sta_info_len=%zu",
			   sub_elem_len, sta_info_len);

		sub_elem_len -= sta_info_len + 2;
		if (sub_elem_len < 4) {
			wpa_printf(MSG_DEBUG, "MLD: Per STA profile too short");
			goto out;
		}

		wpa_hexdump(MSG_MSGDUMP, "MLD: STA profile", pos, sub_elem_len);
		ml_info[i].status = WPA_GET_LE16(pos + 2);

		if (sub_elem_len > ml_len)
			goto out;
		pos += sub_elem_len;
		ml_len -= sub_elem_len;

		i++;
	}

	wpabuf_free(mlbuf);
	return i;
out:
	wpabuf_free(mlbuf);
	return 0;
}

int crypto_bignum_cmp(const struct crypto_bignum *a,
		      const struct crypto_bignum *b)
{
	return BN_cmp((const BIGNUM *) a, (const BIGNUM *) b);
}

#ifdef CONFIG_CTRL_IFACE
int ap_ctrl_iface_chanswitch(struct wpa_supplicant *wpa_s, const char *pos)
{
	struct csa_settings settings;
	struct hostapd_iface *iface = NULL;
	int ret;

#ifdef CONFIG_AP
	if (wpa_s->ap_iface)
		iface = wpa_s->ap_iface;
#endif /* CONFIG_AP */
#ifdef CONFIG_MESH
	if (!iface && wpa_s->ifmsh)
		iface = wpa_s->ifmsh;
#endif /* CONFIG_MESH */

	if (!iface)
		return -1;

	ret = hostapd_parse_csa_settings(iface, pos, &settings);
	if (ret)
		return ret;

	settings.link_id = -1;

	return ap_switch_channel(wpa_s, &settings);
}

/*
** Finish rendering the results
*/
static void qrfFinalize(Qrf *p){
  switch( p->spec.eStyle ){
    case QRF_STYLE_Count: {
      sqlite3_str_appendf(p->pOut, "%lld\n", p->nRow);
      qrfWrite(p);
      break;
    }
    case QRF_STYLE_Json: {
      if( p->nRow>0 ){
        sqlite3_str_append(p->pOut, "}]\n", 3);
        qrfWrite(p);
      }
      break;
    }
    case QRF_STYLE_JObject: {
      if( p->nRow>0 ){
        sqlite3_str_append(p->pOut, "}\n", 2);
        qrfWrite(p);
      }
      break;
    }
    case QRF_STYLE_Line: {
      if( p->u.sLine.azCol ){
        int i;
        for(i=0; i<p->nCol; i++) sqlite3_free(p->u.sLine.azCol[i]);
        sqlite3_free(p->u.sLine.azCol);
      }
      break;
    }
    case QRF_STYLE_Stats:
    case QRF_STYLE_StatsEst: {
      i64 nCycle = 0;
#ifdef SQLITE_ENABLE_STMT_SCANSTATUS
      sqlite3_stmt_scanstatus_v2(p->pStmt, -1, SQLITE_SCANSTAT_NCYCLE,
                                 SQLITE_SCANSTAT_COMPLEX, (void*)&nCycle);
#endif
      qrfEqpRender(p, nCycle);
      qrfWrite(p);
      break;
    }
    case QRF_STYLE_Eqp: {
      qrfEqpRender(p, 0);
      qrfWrite(p);
      break;
    }
  }
  qrfStrErr(p, p->pOut);
  if( p->spec.pzOutput ){
    if( p->spec.pzOutput[0] ){
      sqlite3_int64 n, sz;
      char *zCombined;
      sz = strlen(p->spec.pzOutput[0]);
      n = sqlite3_str_length(p->pOut);
      zCombined = sqlite3_realloc(p->spec.pzOutput[0], sz+n+1);
      if( zCombined==0 ){
        sqlite3_free(p->spec.pzOutput[0]);
        p->spec.pzOutput[0] = 0;
        qrfOom(p);
      }else{
        p->spec.pzOutput[0] = zCombined;
        memcpy(zCombined+sz, sqlite3_str_value(p->pOut), n+1);
      }
      sqlite3_free(sqlite3_str_finish(p->pOut));
    }else{
      p->spec.pzOutput[0] = sqlite3_str_finish(p->pOut);
    }
  }else if( p->pOut ){
    sqlite3_free(sqlite3_str_finish(p->pOut));
  }
  if( p->expMode>0 ){
    sqlite3_stmt_explain(p->pStmt, p->expMode-1);
  }
  if( p->actualWidth ){
    sqlite3_free(p->actualWidth);
  }
  if( p->pJTrans ){
    sqlite3 *db = sqlite3_db_handle(p->pJTrans);
    sqlite3_finalize(p->pJTrans);
    sqlite3_close(db);
  }
}

/**
 * wpa_config_foreach_network - Iterate over each configured network
 * @config: Configuration data from wpa_config_read()
 * @func: Callback function to process each network
 * @arg: Opaque argument to pass to callback function
 *
 * Iterate over the set of configured networks calling the specified
 * function for each item. We guard against callbacks removing the
 * supplied network.
 */
void wpa_config_foreach_network(struct wpa_config *config,
				void (*func)(void *, struct wpa_ssid *),
				void *arg)
{
	struct wpa_ssid *ssid, *next;

	ssid = config->ssid;
	while (ssid) {
		next = ssid->next;
		func(arg, ssid);
		ssid = next;
	}
}

